--
-- Structure de la table `cache_locks`
--

DROP TABLE IF EXISTS `cache_locks`;
CREATE TABLE IF NOT EXISTS `cache_locks` (
  `key` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `owner` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `expiration` bigint NOT NULL,
  PRIMARY KEY (`key`),
  KEY `cache_locks_expiration_index` (`expiration`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Structure de la table `candidatures`
--

DROP TABLE IF EXISTS `candidatures`;
CREATE TABLE IF NOT EXISTS `candidatures` (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `chauffeur_id` bigint UNSIGNED NOT NULL,
  `numero_permis` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `annees_permis` int NOT NULL,
  `numero_carte_vtc` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `numero_piece_identite` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `statut` enum('en_attente','en_cours_examen','rejete','accepte','entretien_programme') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'en_attente',
  `motif_rejet` text COLLATE utf8mb4_unicode_ci,
  `jeton_correction` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `jeton_correction_expire_le` timestamp NULL DEFAULT NULL,
  `examine_par` bigint UNSIGNED DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `candidatures_jeton_correction_unique` (`jeton_correction`),
  KEY `candidatures_chauffeur_id_foreign` (`chauffeur_id`)
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

